"""Format the harness output ("<prn> <2046 0/1 chars>" per line) as the committed fixture."""
import hashlib
import sys

HEADER = """\
# BeiDou B1I primary codes, PRN 1..63, generated by GNSS-SDR v0.0.19
# (beidou_b1i_code_gen_int, src/algorithms/libs/beidou_b1i_signal_replica.cc, chip_shift 0).
# Program output only; see BEIDOU-B1I-PROVENANCE.md. No GNSS-SDR source is in this repository.
# PIN-SCOPE:    all 2046 chips of the B1I primary code of every PRN 1..63, as logic bits
#               (GNSS-SDR value +1 -> 1, -1 -> 0): the first 64 chips as 16 hex digits (MSB =
#               chip 0) and the SHA-256 of the 2046-character ASCII '0'/'1' string of the code.
# PIN-EXCLUDES: the NH20 secondary code, GEO/MEO classification, carrier and chip-rate
#               constants, the D1/D2 navigation data.
# columns: prn first64_hex sha256_of_2046_chip_ascii
"""

out = [HEADER]
for line in open(sys.argv[1]):
    prn, chips = line.split()
    assert len(chips) == 2046 and set(chips) <= {"0", "1"}
    head = "%016x" % int(chips[:64], 2)
    out.append("%s %s %s\n" % (prn, head, hashlib.sha256(chips.encode()).hexdigest()))
sys.stdout.write("".join(out))
